(() => {
  'use strict';
  const DB_KEY = 'careflow_opd_demo_v1';
  const SESSION_KEY = 'careflow_opd_session_v1';
  const safeStorage = (() => {
    try {
      const store = window.localStorage;
      const probe = `${DB_KEY}_storage_test`;
      store.setItem(probe, 'ok');
      store.removeItem(probe);
      return store;
    } catch (error) {
      const memory = new Map();
      return {
        getItem(key) { return memory.has(key) ? memory.get(key) : null; },
        setItem(key, value) { memory.set(key, String(value)); },
        removeItem(key) { memory.delete(key); }
      };
    }
  })();
  const STATUSES = ['Waiting','Called','In Operation','Completed','Cancelled'];
  const DAYS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const fullDays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const todayISO = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const isoDay = (date) => { const d = new Date(date+'T12:00:00'); return d.getDay(); };
  const addDays = (date, n) => { const d = new Date(date+'T12:00:00'); d.setDate(d.getDate()+n); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const fmtDate = (date, options={weekday:'short',month:'short',day:'numeric'}) => date ? new Date(date+'T12:00:00').toLocaleDateString('en-US',options) : '—';
  const fmtTime = (time) => { if (!time) return '—'; const [h,m]=time.split(':').map(Number); const d=new Date(); d.setHours(h,m,0,0); return d.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}); };
  const escapeHTML = (str='') => String(str).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const initials = (name='User') => name.split(/\s+/).filter(Boolean).slice(0,2).map(n=>n[0]).join('').toUpperCase();
  const nextWorkday = (days, offset=1) => { for(let i=offset;i<offset+15;i++){const d=addDays(todayISO(),i);if(days.includes(isoDay(d)))return d;}return addDays(todayISO(),offset); };
  const seed = () => {
    const doctors = [
      {id:'d1',name:'Dr. Ava Wilson',specialty:'Cardiology',department:'Heart Center',qualification:'MD, FACC',room:'Room 204',bio:'Focuses on heart health, preventive cardiology, and long-term cardiac care.',days:[1,2,3,4,5],slots:['09:00','09:30','10:00','10:30','13:30','14:00','14:30'],color:'',active:true},
      {id:'d2',name:'Dr. Noah Patel',specialty:'Dermatology',department:'Skin & Allergy',qualification:'MD, Dermatology',room:'Room 118',bio:'Supports patients with common skin conditions, allergy concerns, and skin health.',days:[1,2,3,4,5,6],slots:['09:30','10:00','10:30','11:00','13:00','14:00','14:30'],color:'v2',active:true},
      {id:'d3',name:'Dr. Sofia Chen',specialty:'Pediatrics',department:'Children’s Clinic',qualification:'MD, Pediatrics',room:'Room 106',bio:'Provides outpatient care and routine assessment for infants, children, and teens.',days:[1,2,3,4,5,6],slots:['08:30','09:00','10:00','10:30','11:00','13:30','14:00'],color:'v3',active:true},
      {id:'d4',name:'Dr. Ethan Brooks',specialty:'Orthopedics',department:'Bone & Joint',qualification:'MD, Orthopedic Surgery',room:'Room 302',bio:'Helps patients with joint, muscle, and mobility-related outpatient concerns.',days:[1,2,3,4,5],slots:['09:00','10:00','10:30','11:00','13:00','13:30','15:00'],color:'v4',active:true},
      {id:'d5',name:'Dr. Mia Robinson',specialty:'General Medicine',department:'General OPD',qualification:'MD, Internal Medicine',room:'Room 101',bio:'Coordinates general outpatient assessment and ongoing care planning.',days:[1,2,3,4,5,6],slots:['08:30','09:00','09:30','10:00','13:00','14:00','15:00'],color:'',active:true},
      {id:'d6',name:'Dr. Oliver James',specialty:'ENT',department:'Ear, Nose & Throat',qualification:'MD, Otolaryngology',room:'Room 220',bio:'Provides outpatient assessment for ear, nose, throat, and sinus concerns.',days:[2,3,4,5,6],slots:['09:00','09:30','10:30','11:00','13:00','14:30'],color:'v2',active:true}
    ];
    const users = [
      {id:'u1',name:'Maya Chen',email:'patient@opd.demo',password:'patient123',role:'patient',phone:'+66 81 234 5678',createdAt:new Date().toISOString()},
      {id:'u2',name:'OPD Admin',email:'admin@opd.demo',password:'admin123',role:'admin',phone:'Hospital Operations',createdAt:new Date().toISOString()},
      {id:'u3',name:'Alex Kim',email:'alex@opd.demo',password:'demo123',role:'patient',phone:'—',createdAt:new Date().toISOString()},
      {id:'u4',name:'Jamie Park',email:'jamie@opd.demo',password:'demo123',role:'patient',phone:'—',createdAt:new Date().toISOString()}
    ];
    const queueDate = nextWorkday([1,2,3,4,5],1);
    const makeAppt = (id,userId,patientName,doctorId,time,queueNo,status) => {const d=doctors.find(x=>x.id===doctorId);return {id,userId,patientName,doctorId,doctorName:d.name,specialty:d.specialty,date:queueDate,time,queueNo,token:String(queueNo).padStart(3,'0'),status,createdAt:new Date().toISOString()};};
    const appointments = [
      makeAppt('a1','u3','Alex Kim','d1','09:00',1,'Waiting'),
      makeAppt('a2','u4','Jamie Park','d1','09:30',2,'Called'),
      makeAppt('a3','u1','Maya Chen','d1','10:00',3,'Waiting'),
      makeAppt('a4','u1','Maya Chen','d2','10:30',1,'Waiting')
    ];
    return {users,doctors,appointments};
  };
  let db;
  try { db = JSON.parse(safeStorage.getItem(DB_KEY) || 'null'); } catch(e) { db=null; }
  if(!db || !Array.isArray(db.users) || !Array.isArray(db.doctors) || !Array.isArray(db.appointments)) { db=seed(); persist(); }
  function persist(){ try { safeStorage.setItem(DB_KEY,JSON.stringify(db)); } catch(e) { console.warn('Demo storage unavailable',e); } }
  // Demo-data migration: add account access state and patient visit notes to older saved records.
  db.users.forEach(u=>{ if(u.role==='patient' && !u.accountStatus) u.accountStatus='Active'; });
  db.appointments.forEach(a=>{ if(typeof a.visitReason!=='string') a.visitReason=''; });
  if(!Array.isArray(db.notifications)) db.notifications=[];
  persist();
  let currentUser = null;
  try { const session=JSON.parse(safeStorage.getItem(SESSION_KEY)||'null'); if(session) currentUser=db.users.find(u=>u.id===session.userId)||null; } catch(e) { currentUser=null; }
  let page = 'overview';
  let doctorSearch = '';
  let doctorSpecialty = 'All specialties';
  let apptFilter = 'all';
  let queueDateFilter = '';
  let adminDoctorSearch = '';
  let adminApptSearch = '';
  let adminApptStatusFilter = 'All statuses';
  let adminPatientSearch = '';
  let notificationOpen = false;
  let rescheduleVisitReason = '';

  const statusClass = s => ({'Waiting':'amber','Called':'blue','In Operation':'purple','Completed':'green','Cancelled':'red'}[s]||'');
  const statusTag = s => `<span class="tag ${statusClass(s)}"><span class="dot"></span>${escapeHTML(s)}</span>`;
  function addNotification(userId,title,message,type='general',relatedId=null){
    if(!Array.isArray(db.notifications)) db.notifications=[];
    db.notifications.push({id:'n'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),userId,title,message,type,relatedId,createdAt:new Date().toISOString(),readAt:null});
    if(db.notifications.length>600) db.notifications=db.notifications.slice(-600);
    refreshNotificationBell();
  }
  function refreshNotificationBell(){
    const wrap=$('#notification-wrap');
    if(wrap) wrap.outerHTML=notificationBell();
  }
  function notifyAdmins(title,message,type='admin',relatedId=null){
    db.users.filter(u=>u.role==='admin').forEach(u=>addNotification(u.id,title,message,type,relatedId));
  }
  function notificationsForCurrentUser(){
    return (db.notifications||[]).filter(n=>n.userId===currentUser?.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
  }
  function notificationTime(value){
    const date=new Date(value);if(Number.isNaN(date.getTime()))return 'Recently';
    const diff=Math.max(0,Math.floor((Date.now()-date.getTime())/1000));
    if(diff<60)return 'Just now';if(diff<3600)return `${Math.floor(diff/60)} min ago`;if(diff<86400)return `${Math.floor(diff/3600)} hr ago`;
    return date.toLocaleDateString('en-US',{month:'short',day:'numeric',year:date.getFullYear()===new Date().getFullYear()?undefined:'numeric'});
  }
  function notificationBell(){
    const items=notificationsForCurrentUser();
    const unread=items.filter(n=>!n.readAt).length;
    const list=items.length?items.slice(0,30).map(n=>`<button type="button" class="notification-item ${n.readAt?'':'unread'}" data-action="mark-notification-read" data-id="${escapeHTML(n.id)}"><span class="notification-item-icon">${n.type==='account'?'♙':n.type==='appointment'?'▤':'•'}</span><span class="notification-item-copy"><strong>${escapeHTML(n.title)}</strong><p>${escapeHTML(n.message)}</p><time>${notificationTime(n.createdAt)}</time></span>${n.readAt?'':'<span class="notification-unread-dot" aria-label="Unread"></span>'}</button>`).join(''):`<div class="notification-empty"><span>♧</span>You’re all caught up. New updates will appear here.</div>`;
    return `<div class="notification-wrap" id="notification-wrap"><button type="button" id="notification-trigger" class="notification-trigger" data-action="toggle-notifications" aria-label="Notifications${unread?`, ${unread} unread`:''}" aria-expanded="${notificationOpen?'true':'false'}" aria-controls="notification-panel"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"></path><path d="M10 21h4"></path></svg>${unread?`<span class="notification-badge">${unread>99?'99+':unread}</span>`:''}</button><section id="notification-panel" class="notification-panel ${notificationOpen?'':'hidden'}" aria-label="Notifications"><header class="notification-head"><strong>Notifications <span class="muted">(${items.length})</span></strong>${unread?'<button type="button" data-action="mark-all-notifications-read">Mark all as read</button>':'<span class="small muted">All caught up</span>'}</header><div class="notification-list">${list}</div></section></div>`;
  }
  // Production integration point: call this when the backend emits a validated status transition.
  // Admin receives a monitoring notification; Admin never edits the appointment status.
  function notifyAppointmentStatusUpdate(appt,previousStatus,newStatus){
    if(!appt||previousStatus===newStatus)return;
    addNotification(appt.userId,'Appointment status updated',`Your appointment with ${appt.doctorName} (token #${appt.token}) changed from ${previousStatus} to ${newStatus}.`,'appointment',appt.id);
    notifyAdmins('Appointment status updated',`${appt.patientName} · ${appt.doctorName} · token #${appt.token}: ${previousStatus} → ${newStatus}.`,'appointment',appt.id);
    persist();
  }
  const accountStatus = user => user?.accountStatus || 'Active';
  const accountStatusTag = user => accountStatus(user)==='Banned' ? '<span class="tag red"><span class="dot"></span>Banned</span>' : '<span class="tag green"><span class="dot"></span>Active</span>';
  const getDoctor = id => db.doctors.find(d=>d.id===id);
  const patientAppts = () => db.appointments.filter(a=>a.userId===currentUser?.id);
  const activeAppts = (list=db.appointments) => list.filter(a=>a.status!=='Cancelled');
  const availableDates = doctor => { const dates=[]; for(let i=1;i<=21;i++){const d=addDays(todayISO(),i);if(doctor.days.includes(isoDay(d)))dates.push(d);}return dates; };
  const slotsFor = (doctor,date,excludeId=null) => doctor.slots.filter(t=>!db.appointments.some(a=>a.id!==excludeId&&a.doctorId===doctor.id&&a.date===date&&a.time===t&&a.status!=='Cancelled'));
  const tokenFor = (doctorId,date) => { const rows=db.appointments.filter(a=>a.doctorId===doctorId&&a.date===date);const max=rows.reduce((m,a)=>Math.max(m,Number(a.queueNo)||0),0);return max+1; };
  const currentQueueRow = appt => {
    if(!appt) return null;
    return db.appointments.filter(a=>a.doctorId===appt.doctorId&&a.date===appt.date&&a.status!=='Cancelled').sort((a,b)=>a.queueNo-b.queueNo);
  };
  const nextPatientAppt = () => patientAppts().filter(a=>a.status!=='Cancelled'&&a.status!=='Completed'&&a.date>=todayISO()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0]||null;
  const countInQueue = () => db.appointments.filter(a=>a.status==='Waiting'||a.status==='Called'||a.status==='In Operation').length;
  const icon = (symbol) => `<span aria-hidden="true">${symbol}</span>`;
  const field = (label,name,value='',type='text',extra='') => `<div class="form-field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${escapeHTML(value)}" ${extra}></div>`;

  function showToast(message,type='success') { const node=document.createElement('div');node.className='toast '+type;node.textContent=message;$('#toast-stack').appendChild(node);setTimeout(()=>node.remove(),3400); }
  function showModal(title,body,foot='',wide=false) { $('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><header class="modal-head"><h2>${escapeHTML(title)}</h2><button class="close-btn" data-action="close-modal" aria-label="Close dialog">×</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-foot">${foot}</footer>`:''}</section></div>`; document.body.style.overflow='hidden'; const focus=$('#modal-root input, #modal-root select, #modal-root button'); if(focus)focus.focus(); }
  function closeModal(){ $('#modal-root').innerHTML='';document.body.style.overflow=''; }
  function loginScreen(register=false){
    $('#app').innerHTML=`<div class="auth-screen">
      <section class="auth-hero"><div class="brand"><span class="brand-mark">+</span><span>CareFlow <span style="font-weight:500;color:#b9e4e7">OPD</span></span></div>
        <div class="auth-copy"><span class="eyebrow" style="color:#8ce4db">OUTPATIENT CARE, CONNECTED</span><h1>Your care journey,<br>without the guesswork.</h1><p>Find the right doctor, choose an available appointment, and follow your token in the queue — all in one place.</p><div class="hero-features"><div class="hero-feature"><strong>01 · Discover</strong>Doctor profiles & schedules</div><div class="hero-feature"><strong>02 · Book</strong>Appointment + token</div><div class="hero-feature"><strong>03 · Track</strong>Live queue status</div></div></div>
        <div class="auth-bottom">CareFlow OPD · Student project prototype · Sample data only</div>
      </section>
      <section class="auth-main"><div class="auth-panel"><div class="eyebrow">${register?'GET STARTED':'WELCOME BACK'}</div><h2>${register?'Create your account':'Sign in to CareFlow'}</h2><p>${register?'Register to book and manage outpatient appointments.':'Use your account to manage appointments and view your upcoming queue number.'}</p>
      ${register?`<form id="register-form">${field('Full name','reg-name','','text','required autocomplete="name"')}${field('Email address','reg-email','','email','required autocomplete="email"')}${field('Phone number (optional)','reg-phone','','tel','autocomplete="tel"')}${field('Password','reg-password','','password','required minlength="6" autocomplete="new-password"')}<button class="btn btn-primary btn-block" type="submit">Create patient account <span>→</span></button></form><p style="margin-top:14px;font-size:12px">Already registered? <button class="text-button" data-action="show-login">Sign in</button></p>`:
      `<form id="login-form">${field('Email address','login-email','patient@opd.demo','email','required autocomplete="username"')}${field('Password','login-password','patient123','password','required autocomplete="current-password"')}<div class="auth-options"><label style="display:flex;align-items:center;gap:6px;color:#72848f"><input type="checkbox" checked style="accent-color:var(--teal)"> Remember this demo session</label><button class="text-button" type="button" data-action="credentials">Demo credentials</button></div><button class="btn btn-primary btn-block" type="submit">Sign in <span>→</span></button></form><div class="auth-divider">OR TRY A DEMO ROLE</div><div class="demo-buttons"><button class="demo-btn" data-action="demo-login" data-role="patient"><strong>♧ Patient portal</strong><span>Browse, book & track tokens</span></button><button class="demo-btn" data-action="demo-login" data-role="admin"><strong>▦ Admin workspace</strong><span>Manage schedules & queues</span></button></div><p style="margin-top:17px;font-size:12px">New to CareFlow? <button class="text-button" data-action="show-register">Create an account</button></p>`}
      <div class="demo-note">Prototype note: this is a front-end demo using sample records stored in this browser. Do not enter real patient or medical information.</div></div></section></div>`;
  }
  function navItem(id,label,symbol){return `<button class="nav-item ${page===id?'active':''}" data-action="navigate" data-page="${id}"><span class="nav-ico">${symbol}</span><span>${label}</span></button>`;}
  function appShell(){
    const isAdmin=currentUser.role==='admin';
    const nav=isAdmin?`${navItem('overview','Dashboard','⌂')}${navItem('appointments','Appointments','▤')}${navItem('patients','Patient accounts','♙')}${navItem('doctors','Doctors & schedules','✚')}${navItem('profile','Admin profile','⚙')}`:`${navItem('overview','Overview','⌂')}${navItem('doctors','Find a doctor','✚')}${navItem('my-appointments','My appointments','▤')}${navItem('my-queue','Token queue','◷')}${navItem('profile','My profile','♙')}`;
    $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark">+</span><span>CareFlow <span style="font-weight:500;color:#8ccbd0">OPD</span></span></div><div class="side-section">${isAdmin?'ADMIN WORKSPACE':'PATIENT PORTAL'}</div><nav class="nav-list">${nav}</nav><div class="sidebar-spacer"></div><div class="sidebar-help"><strong>Need help with your visit?</strong><p>Appointment and token updates are managed by the system. Patient account access is supervised by hospital administration. For urgent medical support, contact hospital staff.</p></div><div class="user-mini"><div class="avatar">${initials(currentUser.name)}</div><div style="min-width:0;flex:1"><strong>${escapeHTML(currentUser.name)}</strong><span>${isAdmin?'System administrator':'Patient account'}</span></div><button class="nav-item" data-action="logout" style="width:auto;padding:8px" title="Sign out">⇥</button></div></aside>
      <main class="main-area"><header class="topbar"><div style="display:flex;align-items:center;gap:12px;min-width:0"><button class="btn btn-secondary btn-sm mobile-menu" data-action="toggle-menu">☰</button><div><div class="crumb">CareFlow / ${isAdmin?'Admin':'Patient'} / ${escapeHTML(pageLabel())}</div><div class="topbar-title">${escapeHTML(pageLabel())}</div></div></div><div class="top-actions"><div class="mini-search"><span>⌕</span><input id="global-search" placeholder="Search doctors…" aria-label="Search doctors" value="${escapeHTML(doctorSearch)}"></div>${notificationBell()}<span class="role-chip">● ${isAdmin?'ADMIN MODE':'PATIENT MODE'}</span><button class="btn btn-secondary btn-sm" data-action="logout">Sign out</button></div></header><div class="content" id="page-content">${renderPage()}</div></main></div>`;
  }
  function pageLabel(){return ({overview:'Overview',doctors:currentUser?.role==='admin'?'Doctors & schedules':'Find a doctor','my-appointments':'My appointments','my-queue':'Token queue',profile:currentUser?.role==='admin'?'Admin profile':'My profile',appointments:'Appointments',patients:'Patient accounts'})[page]||'Overview';}
  function pageIntro(kicker,title,desc,actions=''){return `<div class="page-intro"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
  function statCard(label,value,foot,symbol,tone=''){return `<article class="stat-card"><div><div class="stat-label">${label}</div><div class="stat-value mono">${value}</div><div class="stat-foot">${foot}</div></div><div class="stat-icon ${tone}">${symbol}</div></article>`;}
  function doctorCard(d){const dates=availableDates(d);const soon=dates[0];return `<article class="doctor-card"><div class="doctor-card-top"><div class="doctor-avatar ${d.color||''}">${initials(d.name.replace('Dr. ',''))}</div><div style="min-width:0;flex:1"><h3>${escapeHTML(d.name)}</h3><div class="specialty">${escapeHTML(d.specialty)}</div><div class="muted small" style="margin-top:4px">${escapeHTML(d.department)} · ${escapeHTML(d.room)}</div></div><span class="tag green">Available</span></div><div class="doctor-bio">${escapeHTML(d.bio||'Outpatient consultation and patient care.')}</div><div class="doctor-foot"><div class="availability-line"><strong>${soon?fmtDate(soon,{weekday:'short',month:'short',day:'numeric'}):'Schedule pending'}</strong>${d.slots.length} time slots · ${d.days.map(x=>DAYS[x]).join(', ')}</div><button class="btn btn-primary btn-sm" data-action="book-doctor" data-id="${d.id}">${currentUser.role==='admin'?'Edit schedule':'View times'} →</button></div></article>`;}
  function findDoctorView(admin=false){
    if(admin){
      const list=db.doctors.filter(d=>`${d.name} ${d.specialty} ${d.department}`.toLowerCase().includes(adminDoctorSearch.toLowerCase()));
      return `${pageIntro('OPERATIONS','Doctors & schedules','Maintain doctor profiles and appointment availability for the OPD.','<button class="btn btn-primary" data-action="add-doctor">＋ Add doctor</button>')}<div class="onboarding-strip"><span style="font-size:20px">ⓘ</span><div><strong>Schedule control</strong><br>Only the admin area can add, edit, or remove doctor records. Changes are reflected in the patient directory.</div></div><div class="toolbar"><div class="search-control"><span>⌕</span><input id="admin-doctor-search" placeholder="Search name, specialty, department…" value="${escapeHTML(adminDoctorSearch)}"></div><span class="tag">${list.length} doctors</span></div><div class="grid doctor-grid">${list.length?list.map(d=>`<article class="doctor-card"><div class="doctor-card-top"><div class="doctor-avatar ${d.color||''}">${initials(d.name.replace('Dr. ','').replace('Dr ',''))}</div><div style="flex:1;min-width:0"><h3>${escapeHTML(d.name)}</h3><div class="specialty">${escapeHTML(d.specialty)}</div><div class="muted small" style="margin-top:4px">${escapeHTML(d.department)}</div></div><span class="tag green">${d.active?'Active':'Inactive'}</span></div><div class="doctor-bio">${escapeHTML(d.qualification||'Qualification not provided')} · ${escapeHTML(d.room||'Room not assigned')}</div><div class="note-box"><strong>Clinic days</strong><br>${d.days.map(x=>fullDays[x]).join(', ')}<br><strong>Appointment times</strong><br>${d.slots.map(fmtTime).join(' · ')}</div><div class="doctor-foot"><span class="small muted">${db.appointments.filter(a=>a.doctorId===d.id&&a.status!=='Cancelled').length} active appointments</span><div class="table-actions"><button class="btn btn-secondary btn-sm" data-action="edit-doctor" data-id="${d.id}">Edit</button><button class="btn btn-danger btn-sm" data-action="delete-doctor" data-id="${d.id}">Remove</button></div></div></article>`).join(''):`<div class="panel empty-state" style="grid-column:1/-1"><div class="empty-icon">✚</div><strong>No doctors found</strong>Try a different search or add a doctor.</div>`}</div>`;
    }
    const list=db.doctors.filter(d=>d.active&&`${d.name} ${d.specialty} ${d.department}`.toLowerCase().includes(doctorSearch.toLowerCase())&&(doctorSpecialty==='All specialties'||d.specialty===doctorSpecialty));
    const specialties=[...new Set(db.doctors.filter(d=>d.active).map(d=>d.specialty))].sort();
    return `${pageIntro('DOCTOR DIRECTORY','Find your specialist','Compare doctor profiles, specialties and available times before booking.')}<div class="toolbar"><div class="search-control"><span>⌕</span><input id="doctor-search" placeholder="Search doctor or specialty…" value="${escapeHTML(doctorSearch)}" aria-label="Search doctors"></div><select id="specialty-filter" aria-label="Filter specialty"><option>All specialties</option>${specialties.map(s=>`<option ${s===doctorSpecialty?'selected':''}>${escapeHTML(s)}</option>`).join('')}</select><span class="tag">${list.length} specialists</span></div><div class="grid doctor-grid">${list.length?list.map(doctorCard).join(''):`<div class="panel empty-state" style="grid-column:1/-1"><div class="empty-icon">⌕</div><strong>No matching doctors</strong>Try another name or specialty.</div>`}</div><div class="inline-note">Availability shown is demo schedule data. A time slot is disabled after a confirmed booking, and cancelled slots become available again.</div>`;
  }
  function patientOverview(){
    const mine=patientAppts().filter(a=>a.status!=='Cancelled').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
    const next=nextPatientAppt();
    return `${pageIntro('PATIENT DASHBOARD',`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${escapeHTML(currentUser.name.split(' ')[0])}.`,'Your appointments, doctor availability, and upcoming queue number in one place.','<button class="btn btn-primary" data-action="navigate" data-page="doctors">＋ Book an appointment</button>')}
    <div class="note-box" style="margin-bottom:16px"><strong>Account status:</strong> ${accountStatusTag(currentUser)} <span class="muted">Your account must remain active to book or reschedule appointments.</span></div><div class="grid stats-grid">${statCard('Upcoming appointments',mine.filter(a=>a.date>=todayISO()&&a.status!=='Completed').length,'Your confirmed visits','▤','teal')}${statCard('Doctors available',db.doctors.filter(d=>d.active).length,'Across OPD specialties','✚','')}${statCard('Completed visits',patientAppts().filter(a=>a.status==='Completed').length,'Your visit history','✓','purple')}</div>
    <div class="grid two-col"><section class="panel"><div class="panel-head"><div><h2>Your next appointment</h2><p>Booking details and token number</p></div><button class="link-button" data-action="navigate" data-page="my-appointments">All appointments →</button></div>${next?`<div class="appointment-highlight"><div style="min-width:0;flex:1"><div class="ap-head"><div class="doctor-avatar ${getDoctor(next.doctorId)?.color||''}">${initials(next.doctorName.replace('Dr. ',''))}</div><div><strong>${escapeHTML(next.doctorName)}</strong><div class="muted">${escapeHTML(next.specialty)} · ${escapeHTML(getDoctor(next.doctorId)?.room||'OPD')}</div></div></div><div class="ap-meta"><span>▣ ${fmtDate(next.date,{weekday:'long',month:'short',day:'numeric'})}</span><span>◷ ${fmtTime(next.time)}</span><span>⌖ ${escapeHTML(getDoctor(next.doctorId)?.department||'OPD')}</span></div></div><div class="token-box"><label>Your token</label><strong>#${next.token}</strong><div style="margin-top:5px">${statusTag(next.status)}</div></div></div><div style="display:flex;gap:9px;margin-top:13px;flex-wrap:wrap"><button class="btn btn-secondary btn-sm" data-action="navigate" data-page="my-queue">View upcoming queue number →</button><button class="btn btn-secondary btn-sm" data-action="navigate" data-page="my-appointments">Manage booking</button></div>`:`<div class="empty-state"><div class="empty-icon">▤</div><strong>No upcoming appointment</strong>Book a doctor to receive your token number.<button class="btn btn-primary btn-sm" style="margin-top:12px" data-action="navigate" data-page="doctors">Find a doctor</button></div>`}</section>
      <section class="panel"><div class="panel-head"><div><h2>Upcoming queue number</h2><p>${next?`${escapeHTML(next.doctorName)} · ${fmtDate(next.date)}`:'Your number will appear after booking'}</p></div><span class="tag ${next?'green':''}">${next?'Upcoming':'Not booked'}</span></div>${next?`<div style="padding:23px 14px;text-align:center;border:1px solid var(--line);border-radius:13px;background:#f7fbfb"><div class="small muted">Your assigned queue number</div><div class="queue-big-number" style="font-size:48px;margin:7px 0 10px">#${escapeHTML(next.token)}</div><div class="muted small">${fmtDate(next.date,{weekday:'long',month:'short',day:'numeric'})} · ${fmtTime(next.time)}</div><div style="margin-top:12px">${statusTag(next.status)}</div></div><div class="inline-note">This is your number for the selected appointment. The patient view does not display the active token or the order of other patients.</div>`:`<div class="empty-state"><div class="empty-icon">◷</div><strong>No upcoming number</strong>Book an appointment to receive your queue number.<button class="btn btn-primary btn-sm" style="margin-top:12px" data-action="navigate" data-page="doctors">Find a doctor</button></div>`}</section></div>
    <section class="section-space"><div class="panel-head"><div><h2>Explore our doctors</h2><p>Start with a specialty that fits your needs.</p></div><button class="link-button" data-action="navigate" data-page="doctors">View all doctors →</button></div><div class="grid doctor-grid">${db.doctors.filter(d=>d.active).slice(0,3).map(doctorCard).join('')}</div></section>`;
  }
  function appointmentTable(rows,admin=false,showUser=false,readOnly=false){
    if(!rows.length)return `<div class="empty-state"><div class="empty-icon">▤</div><strong>No appointments found</strong>${admin?'New patient bookings will appear here.':'Your bookings will appear here after you make an appointment.'}</div>`;
    const patientActions=!admin&&!readOnly;
    return `<div class="table-wrap"><table><thead><tr><th>Token / booking</th>${showUser?'<th>Patient</th>':''}<th>Doctor</th><th>Date & time</th>${admin?'':'<th>Reason for visit</th>'}<th>Status</th>${patientActions?'<th>Actions</th>':''}</tr></thead><tbody>${rows.map(a=>{
      let actions='<span class="muted small">No actions</span>';
      if(a.status==='Waiting') actions=`<button class="btn btn-secondary btn-sm" data-action="reschedule" data-id="${a.id}">Reschedule</button><button class="btn btn-danger btn-sm" data-action="cancel-appointment" data-id="${a.id}">Cancel</button>`;
      else if(a.status==='Completed') actions=`<button class="btn btn-secondary btn-sm" data-action="follow-up" data-id="${a.id}" title="Create a new appointment while preserving this completed visit">Book follow-up</button>`;
      else if(a.status==='Called'||a.status==='In Operation') actions='<span class="muted small">Contact hospital staff</span>';
      return `<tr><td><strong class="mono">#${escapeHTML(a.token)}</strong><div class="muted small">${escapeHTML(a.id.toUpperCase())}</div>${a.followUpFor?'<div class="muted small">Follow-up visit</div>':''}</td>${showUser?`<td><div class="patient-cell"><span class="avatar">${initials(a.patientName)}</span><div><strong>${escapeHTML(a.patientName)}</strong><div class="muted small">${escapeHTML(db.users.find(u=>u.id===a.userId)?.email||'')}</div></div></div>`:''}<td><strong>${escapeHTML(a.doctorName)}</strong><div class="muted small">${escapeHTML(a.specialty)}</div></td><td><strong>${fmtDate(a.date,{month:'short',day:'numeric',year:'numeric'})}</strong><div class="muted small">${fmtTime(a.time)}</div></td>${admin?'':`<td style="max-width:230px"><span title="${escapeHTML(a.visitReason||'No reason provided')}">${escapeHTML(a.visitReason||'Not provided')}</span></td>`}<td>${statusTag(a.status)}</td>${patientActions?`<td><div class="table-actions">${actions}</div></td>`:''}</tr>`;
    }).join('')}</tbody></table></div>`;
  }
    function myAppointmentsView(){let rows=patientAppts().slice().sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));if(apptFilter==='upcoming')rows=rows.filter(a=>a.date>=todayISO()&&!['Cancelled','Completed'].includes(a.status));if(apptFilter==='cancelled')rows=rows.filter(a=>a.status==='Cancelled');if(apptFilter==='completed')rows=rows.filter(a=>a.status==='Completed');return `${pageIntro('YOUR VISITS','My appointments','Review your bookings, cancel plans that changed, or select a new available time.','<button class="btn btn-primary" data-action="navigate" data-page="doctors">＋ New appointment</button>')}<div class="toolbar"><select id="my-appt-filter"><option value="all" ${apptFilter==='all'?'selected':''}>All appointments</option><option value="upcoming" ${apptFilter==='upcoming'?'selected':''}>Upcoming</option><option value="completed" ${apptFilter==='completed'?'selected':''}>Completed</option><option value="cancelled" ${apptFilter==='cancelled'?'selected':''}>Cancelled</option></select><span class="tag">${rows.length} records</span></div>${appointmentTable(rows,false,false)}<div class="inline-note">Rescheduling updates the appointment date/time and generates a token for the new doctor/date queue. Cancelled records remain visible for reference.</div>`;}
  function myQueueView(){
    const next=nextPatientAppt();
    if(!next)return `${pageIntro('UPCOMING QUEUE NUMBER','Upcoming queue number','View the queue number assigned to your next outpatient appointment.')}<div class="panel empty-state"><div class="empty-icon">◷</div><strong>No upcoming appointment</strong>Book an appointment to receive your queue number.<button class="btn btn-primary" style="margin-top:12px" data-action="navigate" data-page="doctors">Find a doctor</button></div>`;
    return `${pageIntro('APPOINTMENT QUEUE','Upcoming queue number','Your assigned number and appointment status, without other patients’ queue order.','<button class="btn btn-secondary" data-action="navigate" data-page="my-appointments">My appointments</button>')}<div class="grid two-col"><section class="panel"><div class="panel-head"><div><h2>Your upcoming queue number</h2><p>${fmtDate(next.date,{weekday:'long',month:'long',day:'numeric',year:'numeric'})} · ${fmtTime(next.time)}</p></div>${statusTag(next.status)}</div><div style="padding:24px 14px;text-align:center;border:1px solid var(--line);border-radius:13px;background:#f7fbfb"><div class="small muted">Your assigned number</div><div class="queue-big-number" style="font-size:54px;margin:8px 0 12px">#${escapeHTML(next.token)}</div><strong>${escapeHTML(next.doctorName)}</strong><div class="muted small" style="margin-top:5px">${escapeHTML(next.specialty)} · ${escapeHTML(getDoctor(next.doctorId)?.department||'OPD')}</div><div style="margin-top:13px">${statusTag(next.status)}</div></div><div class="note-box" style="margin-top:15px"><strong>Appointment status: ${escapeHTML(next.status)}</strong><br>${next.status==='Waiting'?'Your appointment is waiting to be called.':next.status==='Called'?'Your number has been called. Please follow the hospital staff’s instructions.':next.status==='In Operation'?'Your appointment is currently in operation.':'Please follow the hospital staff’s instructions for this appointment.'}</div></section><section class="panel"><div class="panel-head"><div><h2>Appointment details</h2><p>Your booking information</p></div></div><div class="profile-detail"><div><div class="small muted">Doctor</div><strong>${escapeHTML(next.doctorName)}</strong></div><div><div class="small muted">Department</div><strong>${escapeHTML(getDoctor(next.doctorId)?.department||'OPD')}</strong></div><div><div class="small muted">Date</div><strong>${fmtDate(next.date,{month:'long',day:'numeric',year:'numeric'})}</strong></div><div><div class="small muted">Time</div><strong>${fmtTime(next.time)}</strong></div></div><div class="inline-note">Only your upcoming queue number is shown here. The prototype does not display the currently active token or the order of other patients.</div></section></div>`;
  }
  function adminOverview(){
    const activeDoctors=db.doctors.filter(d=>d.active).length;
    const patients=db.users.filter(u=>u.role==='patient');
    const activePatients=patients.filter(u=>accountStatus(u)==='Active').length;
    const bannedPatients=patients.length-activePatients;
    const recent=db.appointments.slice().sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)).slice(0,6);
    const waitingCount=db.appointments.filter(a=>a.status==='Waiting').length;
    const inProgressCount=db.appointments.filter(a=>a.status==='Called'||a.status==='In Operation').length;
    const completedCount=db.appointments.filter(a=>a.status==='Completed').length;
    const cancelledCount=db.appointments.filter(a=>a.status==='Cancelled').length;
    return `${pageIntro('HOSPITAL OPERATIONS','OPD dashboard','Monitor appointment activity, queue progress, doctor availability, and patient account access.')}<div class="grid stats-grid">${statCard('Total appointments',db.appointments.length,'All booking records','▤','')}${statCard('Waiting',waitingCount,'System-managed status','◷','amber')}${statCard('In progress',inProgressCount,'Called or in operation','↗','teal')}${statCard('Completed',completedCount,'Completed visits','✓','purple')}</div><div class="grid stats-grid">${statCard('Active doctors',activeDoctors,'Available in directory','✚','teal')}${statCard('Registered patients',patients.length,'Patient accounts','♙','')}${statCard('Active accounts',activePatients,'Can access patient services','✓','teal')}${statCard('Banned accounts',bannedPatients,'Access currently restricted','⊘','amber')}</div><div class="grid two-col"><section class="panel"><div class="panel-head"><div><h2>Recent appointments</h2><p>Read-only overview of current booking records</p></div><button class="link-button" data-action="navigate" data-page="appointments">View all →</button></div>${appointmentTable(recent,true,true,true)}</section><section class="panel"><div class="panel-head"><div><h2>Patient account summary</h2><p>Account access status across registered patients</p></div></div><div class="queue-admin-cards grid" style="grid-template-columns:1fr 1fr"><div class="queue-admin-card"><div class="eyebrow">ACTIVE ACCOUNTS</div><div class="num">${activePatients}</div><p>Access enabled</p></div><div class="queue-admin-card"><div class="eyebrow">BANNED ACCOUNTS</div><div class="num">${bannedPatients}</div><p>Access restricted</p></div></div><div class="note-box" style="margin-top:14px">Admin can manage patient account access, but cannot edit appointment statuses. In production, the backend booking and queue services will own status transitions; this standalone HTML prototype has no connected backend and displays sample status records.</div><button class="btn btn-primary btn-block" style="margin-top:14px" data-action="navigate" data-page="patients">Manage patient accounts →</button></section></div><section class="section-space panel"><div class="panel-head"><div><h2>Appointment status distribution</h2><p>For monitoring only — status values cannot be edited here.</p></div></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(130px,1fr))"><div class="queue-admin-card"><div class="eyebrow">WAITING</div><div class="num">${waitingCount}</div></div><div class="queue-admin-card"><div class="eyebrow">CALLED / IN OPERATION</div><div class="num">${inProgressCount}</div></div><div class="queue-admin-card"><div class="eyebrow">COMPLETED</div><div class="num">${completedCount}</div></div><div class="queue-admin-card"><div class="eyebrow">CANCELLED</div><div class="num">${cancelledCount}</div></div></div></section>`;
  }
  function adminAppointmentsView(){
    let rows=db.appointments.slice().sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));
    if(adminApptSearch) rows=rows.filter(a=>`${a.patientName} ${a.doctorName} ${a.token} ${a.id}`.toLowerCase().includes(adminApptSearch.toLowerCase()));
    if(adminApptStatusFilter!=='All statuses') rows=rows.filter(a=>a.status===adminApptStatusFilter);
    return `${pageIntro('APPOINTMENT MONITORING','Appointments','View patient bookings and their current system-managed statuses. No appointment status controls are available to Admin.')}<div class="note-box" style="margin-bottom:16px"><strong>Read-only appointment records</strong><br>In the production design, the backend booking and queue services will manage status transitions. This standalone HTML prototype has no connected backend, so the displayed statuses are sample records. Admin can search and monitor bookings but cannot edit statuses.</div><div class="toolbar"><div class="search-control"><span>⌕</span><input id="admin-appt-search" value="${escapeHTML(adminApptSearch)}" placeholder="Search patient, doctor or token…"></div><select id="admin-appt-status-filter" aria-label="Filter appointment status"><option ${adminApptStatusFilter==='All statuses'?'selected':''}>All statuses</option>${STATUSES.map(st=>`<option ${adminApptStatusFilter===st?'selected':''}>${st}</option>`).join('')}</select><span class="tag">${rows.length} records</span></div>${appointmentTable(rows,true,true,true)}<div class="inline-note">Appointment details are shown for operational monitoring. Medical visit descriptions are kept in the patient’s booking record and should be shared only with authorized clinical staff.</div>`;
  }
  function adminPatientsView(){
    const all=db.users.filter(u=>u.role==='patient').sort((a,b)=>a.name.localeCompare(b.name));
    const rows=all.filter(u=>`${u.name} ${u.email} ${u.phone||''}`.toLowerCase().includes(adminPatientSearch.toLowerCase()));
    const active=all.filter(u=>accountStatus(u)==='Active').length;
    const banned=all.length-active;
    return `${pageIntro('ACCESS MANAGEMENT','Patient accounts','Review patient account status and restrict or restore access when necessary.')}<div class="grid stats-grid">${statCard('Total patients',all.length,'Registered accounts','♙','')}${statCard('Active accounts',active,'Access enabled','✓','teal')}${statCard('Banned accounts',banned,'Access restricted','⊘','amber')}</div><div class="note-box" style="margin-bottom:16px"><strong>Account access policy</strong><br>Banning an account prevents that patient from signing in to patient services or creating/rescheduling appointments. Existing appointment records are retained. Restoring an account re-enables access; it does not alter appointment statuses.</div><div class="toolbar"><div class="search-control"><span>⌕</span><input id="admin-patient-search" value="${escapeHTML(adminPatientSearch)}" placeholder="Search patient name, email or phone…"></div><span class="tag">${rows.length} patients</span></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Patient</th><th>Contact</th><th>Registered</th><th>Appointments</th><th>Account status</th><th>Access control</th></tr></thead><tbody>${rows.map(u=>{const count=db.appointments.filter(a=>a.userId===u.id).length;return `<tr><td><div class="patient-cell"><span class="avatar">${initials(u.name)}</span><div><strong>${escapeHTML(u.name)}</strong><div class="muted small">${escapeHTML(u.id)}</div></div></div></td><td><strong>${escapeHTML(u.email)}</strong><div class="muted small">${escapeHTML(u.phone||'No phone provided')}</div></td><td>${new Date(u.createdAt||Date.now()).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</td><td>${count}</td><td>${accountStatusTag(u)}${u.bannedReason?`<div class="muted small" title="${escapeHTML(u.bannedReason)}">Reason: ${escapeHTML(u.bannedReason.slice(0,55))}${u.bannedReason.length>55?'…':''}</div>`:''}</td><td>${accountStatus(u)==='Active'?`<button class="btn btn-danger btn-sm" data-action="ban-patient" data-id="${u.id}">Ban account</button>`:`<button class="btn btn-primary btn-sm" data-action="restore-patient" data-id="${u.id}">Restore access</button>`}</td></tr>`;}).join('')}</tbody></table></div>`:`<div class="panel empty-state"><div class="empty-icon">♙</div><strong>No patient accounts found</strong>Try another search term.</div>`}<div class="inline-note">Use account restrictions only according to hospital policy. For a production system, record the administrator, reason, timestamp, and any appeal/review process in an audit log.</div>`;
  }
  function profileView(){
    const u=currentUser;
    const isAdmin=u.role==='admin';
    const roleLabel=isAdmin?'System administrator':'Patient account';
    const memberSince=new Date(u.createdAt||Date.now()).toLocaleDateString('en-US',{month:'long',year:'numeric'});
    const subtitle=isAdmin?'Manage your administrator name and contact information.':'View or update the personal information attached to your patient account.';
    const kicker=isAdmin?'ADMIN SETTINGS':'ACCOUNT SETTINGS';
    const title=isAdmin?'Admin profile':'My profile';
    const accountDetails=isAdmin
      ? `<div style="margin-top:16px"><div class="small muted">Access role</div><strong>Administrator</strong></div><div style="margin-top:16px"><div class="small muted">Workspace access</div><strong>Dashboard, appointments, patients, doctors</strong></div>`
      : `<div style="margin-top:16px"><div class="small muted">Account status</div>${accountStatusTag(u)}</div><div style="margin-top:16px"><div class="small muted">Your bookings</div><strong>${patientAppts().length} appointment records</strong></div>`;
    const note=isAdmin
      ? 'Your profile controls the display name and contact details shown in the Admin workspace. Patient account access and appointment status permissions are not changed here.'
      : 'You can update only your own profile. Your account status and appointment history are displayed here.';
    return `${pageIntro(kicker,title,subtitle)}<div class="grid profile-grid"><section class="panel"><div class="profile-banner"><div class="avatar">${initials(u.name)}</div><div><h2>${escapeHTML(u.name)}</h2><p>${roleLabel} · Member since ${memberSince}</p></div></div><div class="profile-detail"><div><div class="small muted">Email address</div><strong>${escapeHTML(u.email)}</strong></div><div><div class="small muted">${isAdmin?'Contact number':'Phone number'}</div><strong>${escapeHTML(u.phone||'Not provided')}</strong></div><div style="margin-top:16px"><div class="small muted">Account role</div><strong>${roleLabel}</strong></div>${accountDetails}</div></section><section class="panel"><div class="panel-head"><div><h2>${isAdmin?'Administrator information':'Personal information'}</h2><p>Changes are saved for this browser prototype.</p></div></div><form id="profile-form">${field(isAdmin?'Administrator name':'Full name','profile-name',u.name,'text','required autocomplete="name"')}${field('Email address','profile-email',u.email,'email','required autocomplete="email"')}${field(isAdmin?'Contact number':'Phone number','profile-phone',u.phone||'','tel','autocomplete="tel"')}<button class="btn btn-primary" type="submit">Save ${isAdmin?'admin':'profile'} details</button></form><div class="inline-note">${note} This is a frontend demo; production profile changes must be validated and saved by the backend.</div></section></div>`;
  }
  function renderPage(){
    if(!currentUser)return '';
    if(page==='overview')return currentUser.role==='admin'?adminOverview():patientOverview();
    if(page==='doctors')return findDoctorView(currentUser.role==='admin');
    if(page==='my-appointments'&&currentUser.role==='patient')return myAppointmentsView();
    if(page==='my-queue'&&currentUser.role==='patient')return myQueueView();
    if(page==='profile')return profileView();
    if(page==='appointments'&&currentUser.role==='admin')return adminAppointmentsView();
    if(page==='patients'&&currentUser.role==='admin')return adminPatientsView();
    page='overview';return currentUser.role==='admin'?adminOverview():patientOverview();
  }
  function blockedAccountScreen(){$('#app').innerHTML=`<div style="min-height:100vh;display:grid;place-items:center;padding:22px;background:var(--bg)"><section class="panel" style="width:min(560px,100%);text-align:center;padding:34px"><div class="iconbox" style="margin:0 auto 16px;background:var(--redbg);color:var(--red);font-size:26px">!</div><div class="eyebrow" style="color:var(--red)">PATIENT ACCOUNT ACCESS</div><h1 style="margin:8px 0;font-size:27px">Account access is restricted</h1><p class="muted">Hello ${escapeHTML(currentUser.name)}, your patient account is currently ${accountStatusTag(currentUser)}.</p><div class="note-box" style="text-align:left;margin:18px 0"><strong>Reason / support information</strong><br>${escapeHTML(currentUser.bannedReason||'Please contact the hospital administration for more information about your account access.')}</div><p class="small muted">You cannot book or reschedule appointments while access is restricted. Your existing appointment records are retained.</p><button class="btn btn-primary" data-action="logout">Sign out</button></section></div>`;}
  function render(){ if(!currentUser){loginScreen();return;} if(currentUser.role==='patient'&&accountStatus(currentUser)==='Banned'){blockedAccountScreen();return;} if(currentUser.role==='admin'&&['my-appointments','my-queue'].includes(page))page='overview'; if(currentUser.role==='patient'&&['appointments','patients','admin-appointments','admin-queue','token-records'].includes(page))page='overview'; appShell(); }
  function login(user){currentUser=user;try{safeStorage.setItem(SESSION_KEY,JSON.stringify({userId:user.id}));}catch(e){}page='overview';render();if(user.role==='patient'&&accountStatus(user)==='Banned')showToast('This patient account is restricted. Contact hospital administration.','warn');else showToast(`Welcome ${user.name.split(' ')[0]} — you're signed in.`);}
  function logout(){currentUser=null;try{safeStorage.removeItem(SESSION_KEY);}catch(e){}page='overview';closeModal();loginScreen();}
  function go(p){page=p;$('#sidebar')?.classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'});}
  function startBooking(doctorId){if(!currentUser||currentUser.role!=='patient'||accountStatus(currentUser)!=='Active'){showToast('Your account cannot make bookings at this time.','warn');return;}const d=getDoctor(doctorId);if(!d||!d.active)return;let chosenDate=availableDates(d)[0]||'';let chosenTime='';renderBookingModal(d,chosenDate,chosenTime);}
  function renderBookingModal(d,chosenDate,chosenTime){
    const dates=availableDates(d);if(!dates.includes(chosenDate))chosenDate=dates[0]||'';const slots=chosenDate?d.slots:[];
    const existingForDoctorDate=db.appointments.filter(a=>a.userId===currentUser?.id&&a.doctorId===d.id&&a.date===chosenDate&&a.status!=='Cancelled');
    const existingNotice=existingForDoctorDate.length?`<div class="form-alert form-alert-warning" role="status"><strong>Existing appointment found</strong><span>You already have ${existingForDoctorDate.length===1?'an appointment':'appointments'} with this doctor on this date: ${existingForDoctorDate.map(a=>`${fmtTime(a.time)} (token #${escapeHTML(a.token)})`).join(', ')}. The same doctor, date, and time cannot be booked twice. Choose another available time or manage your current booking in My appointments.</span></div>`:'';
    const selectedDuplicate=chosenDate&&chosenTime?db.appointments.find(a=>a.userId===currentUser?.id&&a.doctorId===d.id&&a.date===chosenDate&&a.time===chosenTime&&a.status!=='Cancelled'):null;
    const errorNotice=selectedDuplicate?`<div id="booking-error" class="form-alert form-alert-error" role="alert"><strong>Duplicate appointment detected</strong><span>You already booked this exact appointment (token #${escapeHTML(selectedDuplicate.token)}). Open My appointments to manage the existing booking.</span></div>`:'<div id="booking-error" class="form-alert form-alert-error" role="alert" hidden></div>';
    const body=`<div class="doctor-card-top" style="margin-bottom:18px"><div class="doctor-avatar ${d.color||''}">${initials(d.name.replace('Dr. ',''))}</div><div><h3 style="font-size:15px;margin:0 0 4px">${escapeHTML(d.name)}</h3><div class="specialty">${escapeHTML(d.specialty)}</div><div class="muted small">${escapeHTML(d.qualification||'')} · ${escapeHTML(d.department)} · ${escapeHTML(d.room)}</div></div></div><p class="muted" style="font-size:12px;line-height:1.6">${escapeHTML(d.bio||'')} Choose an available date and appointment time. Fully booked times are disabled.</p>${existingNotice}<form id="booking-form" data-doctor="${d.id}">${errorNotice}<div class="form-field"><label>1. Select a date</label><div class="date-grid">${dates.slice(0,8).map(date=>`<button type="button" class="date-btn ${date===chosenDate?'selected':''}" data-action="select-booking-date" data-id="${d.id}" data-date="${date}"><strong>${fmtDate(date,{weekday:'short',month:'short',day:'numeric'})}</strong><span>${fullDays[isoDay(date)]}</span></button>`).join('')}</div><input type="hidden" id="booking-date" name="date" value="${chosenDate}"></div><div class="form-field"><label>2. Select an available time</label><div class="slot-grid">${slots.map(time=>{const ownBooking=db.appointments.find(a=>a.userId===currentUser?.id&&a.doctorId===d.id&&a.date===chosenDate&&a.time===time&&a.status!=='Cancelled');const available=slotsFor(d,chosenDate).includes(time);return `<button type="button" class="slot-btn ${time===chosenTime?'selected':''}" data-action="select-booking-time" data-time="${time}" ${available?'':'disabled'}>${fmtTime(time)}${ownBooking?' · Your booking':''}</button>`}).join('')}</div><input type="hidden" id="booking-time" name="time" value="${chosenTime}"></div><div class="form-field"><label for="visit-reason">3. Reason for visit / Medical condition <span class="muted" style="font-weight:500">(optional)</span></label><textarea id="visit-reason" name="visitReason" rows="4" maxlength="500" placeholder="Briefly describe your symptoms or the reason for this appointment…" style="resize:vertical;min-height:105px"></textarea><div class="small muted">Please share only information relevant to this visit. Do not use this form for emergencies. This demo saves the note in this browser only. A production system must restrict it to you and authorized clinical staff.</div></div><div class="note-box"><strong>Automatic token generation</strong><br>After confirmation, the system assigns a token number and stores your booking details and visit note in this browser demo.</div></form>`;
    showModal('Book an appointment',body,`<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="confirm-booking" data-id="${d.id}" ${chosenDate&&chosenTime?'':'disabled'}>Confirm booking →</button>`,true);
  }
  function showBookingError(message){
    const box=$('#booking-error');
    if(box){box.textContent=message;box.hidden=false;box.setAttribute('tabindex','-1');box.focus();}
    showToast(message,'warn');
  }
  function refreshBookingSelection(action, value){const form=$('#booking-form');if(!form)return;const d=getDoctor(form.dataset.doctor);const dateInput=$('#booking-date');const timeInput=$('#booking-time');let date=dateInput.value,time=timeInput.value;if(action==='date'){date=value;time='';}else if(action==='time'){time=value;}if(dateInput)dateInput.value=date;if(timeInput)timeInput.value=time;renderBookingModal(d,date,time);}
  function createBooking(doctorId,date,time,oldId=null,visitReason='',followUpFor=null){
    if(!currentUser||currentUser.role!=='patient'||accountStatus(currentUser)!=='Active')throw new Error('Your patient account is not active. Please contact hospital administration.');
    const d=getDoctor(doctorId);
    if(!d||!d.active)throw new Error('This doctor is not available.');
    if(!d.days.includes(isoDay(date)))throw new Error('This doctor is not scheduled on the selected date.');
    if(!d.slots.includes(time))throw new Error('Please select one of the offered time slots.');
    const duplicateForPatient=db.appointments.find(a=>a.id!==oldId&&a.userId===currentUser.id&&a.doctorId===doctorId&&a.date===date&&a.time===time&&a.status!=='Cancelled');
    if(duplicateForPatient)throw new Error(`You already booked this appointment with ${d.name} at ${fmtTime(time)} on ${fmtDate(date)} (token #${duplicateForPatient.token}). Please use My appointments to review or manage the existing booking.`);
    if(!slotsFor(d,date,oldId).includes(time))throw new Error('This time slot has already been booked by another patient. Please choose a different time.');
    const queueNo=tokenFor(doctorId,date);
    if(oldId){
      const old=db.appointments.find(a=>a.id===oldId);
      if(!old||old.userId!==currentUser.id)throw new Error('Appointment could not be found.');
      if(old.status!=='Waiting')throw new Error('Only a waiting appointment can be rescheduled. Completed visits must use the follow-up option.');
      old.doctorId=doctorId;old.doctorName=d.name;old.specialty=d.specialty;old.date=date;old.time=time;old.queueNo=queueNo;old.token=String(queueNo).padStart(3,'0');old.status='Waiting';old.createdAt=new Date().toISOString();
      if(visitReason.trim())old.visitReason=visitReason.trim();
      addNotification(currentUser.id,'Appointment rescheduled',`Your appointment with ${d.name} is now scheduled for ${fmtDate(date)} at ${fmtTime(time)}. Your new token is #${old.token}.`,'appointment',old.id);
      notifyAdmins('Appointment rescheduled',`${currentUser.name} rescheduled an appointment with ${d.name} to ${fmtDate(date)} at ${fmtTime(time)} (token #${old.token}).`,'appointment',old.id);
      persist();return old;
    }
    if(followUpFor){
      const original=db.appointments.find(a=>a.id===followUpFor&&a.userId===currentUser.id);
      if(!original||original.status!=='Completed')throw new Error('A follow-up can only be created from one of your completed visits.');
    }
    const appt={id:'a'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),userId:currentUser.id,patientName:currentUser.name,doctorId,doctorName:d.name,specialty:d.specialty,date,time,queueNo,token:String(queueNo).padStart(3,'0'),status:'Waiting',visitReason:visitReason.trim(),createdAt:new Date().toISOString(),...(followUpFor?{followUpFor}: {})};
    db.appointments.push(appt);
    addNotification(currentUser.id,followUpFor?'Follow-up appointment confirmed':'Appointment confirmed',`${followUpFor?'Your follow-up appointment':'Your appointment'} with ${d.name} is booked for ${fmtDate(date)} at ${fmtTime(time)}. Your token is #${appt.token}.`,'appointment',appt.id);
    notifyAdmins(followUpFor?'New follow-up appointment booked':'New appointment booked',`${currentUser.name} booked ${d.name} for ${fmtDate(date)} at ${fmtTime(time)} (token #${appt.token}).`,'appointment',appt.id);
    persist();return appt;
  }
    function showBookingSuccess(appt){closeModal();showModal('Appointment confirmed',`<div style="text-align:center;padding:5px 3px 12px"><div class="iconbox" style="margin:0 auto 13px;width:54px;height:54px;font-size:28px;border-radius:18px">✓</div><div class="eyebrow">BOOKING SUCCESSFUL</div><h2 style="font-size:25px;margin:7px 0 8px">Your token is <span style="color:var(--teal)">#${appt.token}</span></h2><p class="muted" style="font-size:12px;line-height:1.6">${escapeHTML(appt.doctorName)} · ${escapeHTML(appt.specialty)}<br>${fmtDate(appt.date,{weekday:'long',month:'long',day:'numeric',year:'numeric'})} at ${fmtTime(appt.time)}</p><div class="note-box" style="text-align:left;margin-top:16px"><strong>Next step</strong><br>Use the Token queue page to view your upcoming queue number and appointment status. Your token status is currently Waiting.</div></div>`,`<button class="btn btn-secondary" data-action="close-modal">Close</button><button class="btn btn-primary" data-action="booking-success-queue">View token queue →</button>`);}
  function rescheduleModal(appt){
    const d=getDoctor(appt.doctorId);const dates=availableDates(d);let chosenDate=dates.find(date=>slotsFor(d,date,appt.status==='Waiting'?appt.id:null).length>0)||dates[0]||'';
    rescheduleVisitReason='';showRescheduleModal(appt,chosenDate,'');
  }
  function showRescheduleModal(appt,date,time){
    const d=getDoctor(appt.doctorId);const isFollowUp=appt.status==='Completed';const dates=availableDates(d);const excludeId=isFollowUp?null:appt.id;
    if(!dates.includes(date))date=dates[0]||'';
    const validSlots=slotsFor(d,date,excludeId);
    const body=`<div class="note-box" style="margin-bottom:16px"><strong>${isFollowUp?'Completed visit':'Current booking'}: #${appt.token}</strong><br>${escapeHTML(appt.doctorName)} · ${fmtDate(appt.date)} at ${fmtTime(appt.time)}${isFollowUp?'<br><b>This completed visit will remain unchanged. A separate follow-up appointment and token will be created.</b>':''}</div><form id="reschedule-form" data-id="${appt.id}"><div class="form-field"><label>${isFollowUp?'Choose a follow-up date':'Choose a new date'}</label><div class="date-grid">${dates.slice(0,8).map(x=>`<button type="button" class="date-btn ${x===date?'selected':''}" data-action="select-reschedule-date" data-id="${appt.id}" data-date="${x}"><strong>${fmtDate(x,{weekday:'short',month:'short',day:'numeric'})}</strong><span>${fullDays[isoDay(x)]}</span></button>`).join('')}</div><input id="reschedule-date" type="hidden" value="${date}"></div><div class="form-field"><label>${isFollowUp?'Choose a follow-up time':'Choose a new time'}</label><div class="slot-grid">${d.slots.map(t=>`<button type="button" class="slot-btn ${t===time?'selected':''}" data-action="select-reschedule-time" data-time="${t}" ${validSlots.includes(t)?'':'disabled'}>${fmtTime(t)}</button>`).join('')}</div><input id="reschedule-time" type="hidden" value="${time}"></div><div class="form-field"><label for="reschedule-visit-reason">${isFollowUp?'Reason for follow-up':'Updated reason for visit'} <span class="muted" style="font-weight:500">(optional)</span></label><textarea id="reschedule-visit-reason" rows="3" maxlength="500" placeholder="Briefly describe the reason for this visit…" style="width:100%;resize:vertical;min-height:85px;border:1px solid var(--line);border-radius:10px;padding:11px">${escapeHTML(rescheduleVisitReason)}</textarea></div></form>`;
    const action=isFollowUp?'confirm-followup':'confirm-reschedule';
    const label=isFollowUp?'Book follow-up':'Save new time';
    showModal(isFollowUp?'Schedule follow-up appointment':'Reschedule appointment',body,`<button class="btn btn-secondary" data-action="close-modal">${isFollowUp?'Cancel':'Keep current booking'}</button><button class="btn btn-primary" data-action="${action}" data-id="${appt.id}" ${date&&time&&validSlots.includes(time)?'':'disabled'}>${label}</button>`,true);
  }
    function refreshReschedule(action,value){const id=$('#reschedule-form')?.dataset.id;const appt=db.appointments.find(a=>a.id===id);if(!appt)return;let date=$('#reschedule-date').value,time=$('#reschedule-time').value;if(action==='date'){date=value;time='';}else time=value;showRescheduleModal(appt,date,time);}
  function doctorEditor(id=null){const d=id?getDoctor(id):{id:'',name:'',specialty:'General Medicine',department:'General OPD',qualification:'',room:'',bio:'',days:[1,2,3,4,5],slots:['09:00','09:30','10:00','13:00'],color:'',active:true};const body=`<form id="doctor-form" data-id="${id||''}"><div class="form-row">${field('Doctor name','doctor-name',d.name,'text','required')}${field('Specialty','doctor-specialty',d.specialty,'text','required')}</div><div class="form-row">${field('Department','doctor-department',d.department,'text','required')}${field('Room','doctor-room',d.room,'text','required')}</div>${field('Qualification','doctor-qualification',d.qualification,'text')}${field('Short profile','doctor-bio',d.bio,'text')}<div class="form-field"><label>Clinic days</label><div class="check-row">${fullDays.map((day,i)=>`<label class="check-pill"><input type="checkbox" name="doctor-days" value="${i}" ${d.days.includes(i)?'checked':''}>${day.slice(0,3)}</label>`).join('')}</div></div>${field('Appointment times (comma-separated 24-hour time)','doctor-slots',d.slots.join(', '),'text','required placeholder="09:00, 09:30, 10:00"')}<p class="muted small" style="margin-top:-7px">Use 24-hour times such as 09:30 or 14:00. These times will be offered for each selected clinic day.</p></form>`;showModal(id?'Edit doctor & schedule':'Add doctor',body,`<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-doctor">Save doctor</button>`,true);}

  document.addEventListener('click',e=>{
    if(notificationOpen&&!e.target.closest('#notification-wrap')){notificationOpen=false;$('#notification-panel')?.classList.add('hidden');$('#notification-trigger')?.setAttribute('aria-expanded','false');}
    const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
    if(action==='toggle-notifications'){notificationOpen=!notificationOpen;const panel=$('#notification-panel');panel?.classList.toggle('hidden',!notificationOpen);$('#notification-trigger')?.setAttribute('aria-expanded',notificationOpen?'true':'false');return;}
    if(action==='mark-notification-read'){const n=db.notifications.find(x=>x.id===b.dataset.id&&x.userId===currentUser?.id);if(n&&!n.readAt){n.readAt=new Date().toISOString();persist();}notificationOpen=true;render();return;}
    if(action==='mark-all-notifications-read'){const now=new Date().toISOString();db.notifications.filter(n=>n.userId===currentUser?.id&&!n.readAt).forEach(n=>n.readAt=now);persist();notificationOpen=true;render();return;}
    if(action==='backdrop'&&e.target.classList.contains('modal-backdrop')){closeModal();return;}
    if(action==='close-modal'){closeModal();return;}
    if(action==='show-login'){loginScreen(false);return;}
    if(action==='show-register'){loginScreen(true);return;}
    if(action==='credentials'){showModal('Demo credentials',`<p class="muted" style="font-size:12px">Use either set to explore the different role permissions.</p><div class="note-box"><strong>Patient</strong><br>Email: patient@opd.demo<br>Password: patient123</div><div class="note-box" style="margin-top:10px"><strong>Admin</strong><br>Email: admin@opd.demo<br>Password: admin123</div><p class="small muted">The sign-in flow is simulated and passwords are stored locally for demo purposes only.</p>`,`<button class="btn btn-primary" data-action="close-modal">Got it</button>`);return;}
    if(action==='demo-login'){const user=db.users.find(u=>u.role===b.dataset.role&&(u.email===(b.dataset.role==='admin'?'admin@opd.demo':'patient@opd.demo')));if(user)login(user);return;}
    if(action==='logout'){logout();return;}
    if(action==='navigate'){go(b.dataset.page);return;}
    if(action==='toggle-menu'){$('#sidebar')?.classList.toggle('open');return;}
    if(action==='book-doctor'){const d=getDoctor(b.dataset.id);if(currentUser.role==='admin')doctorEditor(d.id);else startBooking(d.id);return;}
    if(action==='select-booking-date'){refreshBookingSelection('date',b.dataset.date);return;}
    if(action==='select-booking-time'){refreshBookingSelection('time',b.dataset.time);return;}
    if(action==='confirm-booking'){const form=$('#booking-form');const date=$('#booking-date')?.value;const time=$('#booking-time')?.value;const visitReason=$('#visit-reason')?.value||'';try{if(!date||!time)throw new Error('Please choose a date and time first.');const appt=createBooking(b.dataset.id,date,time,null,visitReason);showBookingSuccess(appt);}catch(err){showBookingError(err.message);}return;}
    if(action==='booking-success-queue'){closeModal();go('my-queue');return;}
    if(action==='cancel-appointment'){const appt=db.appointments.find(a=>a.id===b.dataset.id);if(!appt||appt.userId!==currentUser.id||appt.status!=='Waiting')return;showModal('Cancel appointment',`<p>Are you sure you want to cancel your appointment with <strong>${escapeHTML(appt.doctorName)}</strong> on <strong>${fmtDate(appt.date)} at ${fmtTime(appt.time)}</strong>?</p><div class="note-box">Token #${appt.token} will be cancelled by the booking workflow and removed from the active waiting queue. The record will remain in your history.</div>`,`<button class="btn btn-secondary" data-action="close-modal">Keep appointment</button><button class="btn btn-danger" data-action="confirm-cancel" data-id="${appt.id}">Yes, cancel appointment</button>`);return;}
    if(action==='confirm-cancel'){const appt=db.appointments.find(a=>a.id===b.dataset.id);if(appt&&appt.userId===currentUser.id&&appt.status==='Waiting'){appt.status='Cancelled';addNotification(currentUser.id,'Appointment cancelled',`Your appointment with ${appt.doctorName} on ${fmtDate(appt.date)} was cancelled.`,'appointment',appt.id);notifyAdmins('Patient cancelled an appointment',`${currentUser.name} cancelled token #${appt.token} with ${appt.doctorName} on ${fmtDate(appt.date)}.`,'appointment',appt.id);persist();closeModal();render();showToast(`Appointment token #${appt.token} cancelled.`);}return;}
    if(action==='reschedule'||action==='follow-up'){const appt=db.appointments.find(a=>a.id===b.dataset.id);if(appt&&appt.userId===currentUser.id&&((action==='reschedule'&&appt.status==='Waiting')||(action==='follow-up'&&appt.status==='Completed')))rescheduleModal(appt);return;}
    if(action==='select-reschedule-date'){refreshReschedule('date',b.dataset.date);return;}
    if(action==='select-reschedule-time'){refreshReschedule('time',b.dataset.time);return;}
    if(action==='confirm-reschedule'){const appt=db.appointments.find(a=>a.id===b.dataset.id);const date=$('#reschedule-date')?.value;const time=$('#reschedule-time')?.value;const visitReason=$('#reschedule-visit-reason')?.value||rescheduleVisitReason;if(!appt||appt.userId!==currentUser.id||appt.status!=='Waiting'||!date||!time){showToast('Choose an available date and time first.','warn');return;}try{const updated=createBooking(appt.doctorId,date,time,appt.id,visitReason);rescheduleVisitReason='';closeModal();render();showToast(`Appointment rescheduled. Your new token is #${updated.token}.`);}catch(err){showToast(err.message,'warn');}return;}
    if(action==='confirm-followup'){const appt=db.appointments.find(a=>a.id===b.dataset.id);const date=$('#reschedule-date')?.value;const time=$('#reschedule-time')?.value;const visitReason=$('#reschedule-visit-reason')?.value||rescheduleVisitReason;if(!appt||appt.userId!==currentUser.id||appt.status!=='Completed'||!date||!time){showToast('Choose an available follow-up date and time first.','warn');return;}try{const followUp=createBooking(appt.doctorId,date,time,null,visitReason,appt.id);rescheduleVisitReason='';closeModal();render();showToast(`Follow-up appointment booked. Your new token is #${followUp.token}.`);}catch(err){showToast(err.message,'warn');}return;}
    if(action==='add-doctor'){doctorEditor();return;}
    if(action==='edit-doctor'){doctorEditor(b.dataset.id);return;}
    if(action==='save-doctor'){const form=$('#doctor-form');if(form)saveDoctorForm(form);return;}
    if(action==='delete-doctor'){const d=getDoctor(b.dataset.id);if(!d)return;const hasActive=db.appointments.some(a=>a.doctorId===d.id&&!['Cancelled','Completed'].includes(a.status));if(hasActive){showModal('Doctor has active appointments',`<p><strong>${escapeHTML(d.name)}</strong> has active appointment/token records.</p><div class="note-box">To protect existing bookings, this prototype will not remove a doctor with active queue records. Existing bookings must be handled by the booking/queue workflow; Admin cannot manually change their statuses.</div>`,`<button class="btn btn-primary" data-action="close-modal">Understood</button>`);return;}showModal('Remove doctor',`<p>Remove <strong>${escapeHTML(d.name)}</strong> from the patient directory?</p><div class="note-box">This action hides the doctor from new bookings. Existing token records are retained.</div>`,`<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-danger" data-action="confirm-delete-doctor" data-id="${d.id}">Remove doctor</button>`);return;}
    if(action==='confirm-delete-doctor'){const d=getDoctor(b.dataset.id);if(d){d.active=false;persist();closeModal();render();showToast('Doctor removed from the patient directory.');}return;}
    if(action==='ban-patient'){const u=db.users.find(x=>x.id===b.dataset.id&&x.role==='patient');if(!u)return;showModal('Ban patient account',`<p>Restrict patient access for <strong>${escapeHTML(u.name)}</strong>?</p><div class="form-field"><label for="ban-reason">Reason / message to patient (optional)</label><textarea id="ban-reason" rows="3" maxlength="300" placeholder="Enter a brief reason or contact instruction…" style="width:100%;border:1px solid var(--line);border-radius:10px;padding:10px"></textarea></div><div class="note-box">The patient will be unable to sign in to patient services or book/reschedule appointments. Existing appointment records will not be deleted or have their statuses changed.</div>`,`<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-danger" data-action="confirm-ban-patient" data-id="${u.id}">Ban account</button>`);return;}
    if(action==='confirm-ban-patient'){const u=db.users.find(x=>x.id===b.dataset.id&&x.role==='patient');if(!u)return;u.accountStatus='Banned';u.bannedAt=new Date().toISOString();u.bannedReason=$('#ban-reason')?.value.trim()||'';addNotification(u.id,'Account access restricted',u.bannedReason?`Your account access has been restricted. Reason: ${u.bannedReason}`:'Your account access has been restricted. Please contact hospital administration for assistance.','account',u.id);notifyAdmins('Patient account restricted',`${u.name}'s patient account was banned by hospital administration.`,'account',u.id);persist();closeModal();render();showToast(`${u.name}'s account access has been restricted.`);return;}
    if(action==='restore-patient'){const u=db.users.find(x=>x.id===b.dataset.id&&x.role==='patient');if(!u)return;u.accountStatus='Active';delete u.bannedAt;delete u.bannedReason;addNotification(u.id,'Account access restored','Your patient account is active again. You can sign in and use appointment services.','account',u.id);notifyAdmins('Patient account restored',`${u.name}'s patient account access was restored.`,'account',u.id);persist();render();showToast(`${u.name}'s account access has been restored.`);return;}
  });

  function saveDoctorForm(form){const fd=new FormData(form);const id=form.dataset.id;const name=String(fd.get('doctor-name')||'').trim();const specialty=String(fd.get('doctor-specialty')||'').trim();const department=String(fd.get('doctor-department')||'').trim();const room=String(fd.get('doctor-room')||'').trim();const qualification=String(fd.get('doctor-qualification')||'').trim();const bio=String(fd.get('doctor-bio')||'').trim();const dayValues=fd.getAll('doctor-days').map(Number);const rawSlots=String(fd.get('doctor-slots')||'');const slots=[...new Set(rawSlots.split(',').map(s=>s.trim()))].filter(Boolean);const validTime=s=>/^([01]\d|2[0-3]):[0-5]\d$/.test(s);if(!name||!specialty||!department||!room){showToast('Please complete the required doctor fields.','warn');return;}if(!dayValues.length){showToast('Choose at least one clinic day.','warn');return;}if(!slots.length||slots.some(s=>!validTime(s))){showToast('Use valid 24-hour times separated by commas, e.g. 09:00, 09:30.','warn');return;}if(id){const d=getDoctor(id);Object.assign(d,{name,specialty,department,room,qualification,bio,days:dayValues,slots,active:true});}else{db.doctors.push({id:'d'+Date.now().toString(36),name,specialty,department,room,qualification,bio,days:dayValues,slots,active:true,color:['','v2','v3','v4'][db.doctors.length%4]});}persist();closeModal();render();showToast(id?'Doctor details and schedule saved.':'New doctor added to the directory.');}

  document.addEventListener('submit',e=>{
    if(e.target.id==='login-form'){e.preventDefault();const email=$('#login-email').value.trim().toLowerCase();const password=$('#login-password').value;const user=db.users.find(u=>u.email.toLowerCase()===email&&u.password===password);if(!user){showToast('Email or password was not recognized. Try a demo role.','warn');return;}login(user);}
    if(e.target.id==='register-form'){e.preventDefault();const name=$('#reg-name').value.trim();const email=$('#reg-email').value.trim().toLowerCase();const phone=$('#reg-phone').value.trim();const password=$('#reg-password').value;if(!name||!email||password.length<6){showToast('Enter your name, a valid email and a password with at least 6 characters.','warn');return;}if(db.users.some(u=>u.email.toLowerCase()===email)){showToast('An account with that email already exists. Please sign in.','warn');return;}const user={id:'u'+Date.now().toString(36),name,email,password,phone,role:'patient',accountStatus:'Active',createdAt:new Date().toISOString()};db.users.push(user);notifyAdmins('New patient registered',`${name} created a patient account.`,'account',user.id);persist();login(user);}
    if(e.target.id==='profile-form'){e.preventDefault();const name=$('#profile-name').value.trim();const email=$('#profile-email').value.trim().toLowerCase();const phone=$('#profile-phone').value.trim();if(!name||!email){showToast('Name and email are required.','warn');return;}if(db.users.some(u=>u.id!==currentUser.id&&u.email.toLowerCase()===email)){showToast('That email is already in use.','warn');return;}currentUser.name=name;currentUser.email=email;currentUser.phone=phone;const ix=db.users.findIndex(u=>u.id===currentUser.id);if(ix>=0)db.users[ix]=currentUser;if(currentUser.role==='patient')db.appointments.filter(a=>a.userId===currentUser.id).forEach(a=>a.patientName=name);persist();render();showToast(currentUser.role==='admin'?'Administrator profile has been saved.':'Your profile has been saved.');}
  });
  document.addEventListener('input',e=>{
    if(e.target.id==='reschedule-visit-reason') rescheduleVisitReason=e.target.value;
  });
  document.addEventListener('change',e=>{
    if(e.target.id==='specialty-filter'){doctorSpecialty=e.target.value;render();}
    if(e.target.id==='my-appt-filter'){apptFilter=e.target.value;render();}
    if(e.target.id==='admin-appt-status-filter'){adminApptStatusFilter=e.target.value;render();}
    if(e.target.id==='admin-doctor-search'){adminDoctorSearch=e.target.value;render();const input=$('#admin-doctor-search');if(input){input.focus();input.setSelectionRange(input.value.length,input.value.length);}}
    if(e.target.id==='admin-appt-search'){adminApptSearch=e.target.value;render();}
    if(e.target.id==='admin-patient-search'){adminPatientSearch=e.target.value;render();}
  });
  document.addEventListener('input',e=>{
    if(e.target.id==='doctor-search'){doctorSearch=e.target.value;const caret=e.target.selectionStart;const content=$('#page-content');if(content&&page==='doctors'&&currentUser?.role==='patient'){content.innerHTML=findDoctorView(false);const next=$('#doctor-search');next?.focus();next?.setSelectionRange(caret,caret);}}
    if(e.target.id==='global-search'){doctorSearch=e.target.value;if(page!=='doctors'){page='doctors';render();const next=$('#doctor-search');next?.focus();next?.setSelectionRange(doctorSearch.length,doctorSearch.length);}else {const content=$('#page-content');if(content&&currentUser?.role==='patient'){content.innerHTML=findDoctorView(false);const next=$('#doctor-search');next?.focus();next?.setSelectionRange(doctorSearch.length,doctorSearch.length);}}}
    if(e.target.id==='admin-doctor-search'){adminDoctorSearch=e.target.value;const caret=e.target.selectionStart;const content=$('#page-content');if(content&&page==='doctors'&&currentUser?.role==='admin'){content.innerHTML=findDoctorView(true);const next=$('#admin-doctor-search');next?.focus();next?.setSelectionRange(caret,caret);}}
    if(e.target.id==='admin-appt-search'){adminApptSearch=e.target.value;const caret=e.target.selectionStart;const content=$('#page-content');if(content&&page==='appointments'&&currentUser?.role==='admin'){content.innerHTML=adminAppointmentsView();const next=$('#admin-appt-search');next?.focus();next?.setSelectionRange(caret,caret);}}
    if(e.target.id==='admin-patient-search'){adminPatientSearch=e.target.value;const caret=e.target.selectionStart;const content=$('#page-content');if(content&&page==='patients'&&currentUser?.role==='admin'){content.innerHTML=adminPatientsView();const next=$('#admin-patient-search');next?.focus();next?.setSelectionRange(caret,caret);}}
  });
  window.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal-root').innerHTML)closeModal();if(e.key==='Escape'&&notificationOpen){notificationOpen=false;$('#notification-panel')?.classList.add('hidden');$('#notification-trigger')?.setAttribute('aria-expanded','false');}});
  try {
    render();
  } catch (error) {
    console.error('CareFlow OPD startup error:', error);
    const app = document.getElementById('app');
    if (app) {
      const detail = error && error.message ? error.message : 'Unknown startup error';
      app.innerHTML = `<main style="min-height:100vh;display:grid;place-items:center;padding:24px;background:#f5f8fa;font-family:Arial,sans-serif;color:#172b3a"><section style="width:min(560px,100%);padding:28px;border:1px solid #e3ebef;border-radius:18px;background:#fff;box-shadow:0 14px 35px rgba(25,54,73,.08)"><div style="font-size:12px;font-weight:800;letter-spacing:.1em;color:#087f8c">CAREFLOW OPD</div><h1 style="font-size:24px;margin:10px 0">The prototype could not start</h1><p style="color:#6b7f8d;line-height:1.6">The page opened, but an error occurred while loading the demo. Try resetting the locally saved demo data and reopening this file.</p><div style="padding:12px;border-radius:10px;background:#fff0f0;color:#8f3434;font-size:12px;overflow-wrap:anywhere">${escapeHTML(detail)}</div><button id="reset-demo-data" type="button" style="margin-top:18px;padding:11px 15px;border:0;border-radius:10px;background:#087f8c;color:#fff;font-weight:700;cursor:pointer">Reset demo data and reload</button><p style="font-size:11px;color:#81919a;margin:14px 0 0">Resetting removes only this prototype's locally saved sample data from this browser.</p></section></main>`;
      const resetButton = document.getElementById('reset-demo-data');
      if (resetButton) resetButton.addEventListener('click', () => {
        try {
          safeStorage.removeItem(DB_KEY);
          safeStorage.removeItem(SESSION_KEY);
        } catch (storageError) {
          console.warn('Could not clear local demo storage:', storageError);
        }
        window.location.reload();
      });
    }
  }
})();
